36. // Inlined from `sync/spin.rs`.
37. // These declarations preserve the spin-lock proof interface used below. Their
38. // executable implementations are intentionally external in this standalone
39. // harness.
40. #[verifier::reject_recursive_types(T)]
41. #[verifier::reject_recursive_types(G)]
42. pub struct SpinLock<T, G, P: SpinLockPredicate<T>> {
43.     predicate: Ghost<P>,
44.     phantom: PhantomData<(T, G)>,
45. }
46. 
47. impl<T, G, P: SpinLockPredicate<T>> SpinLock<T, G, P> {
48.     #[verifier::external_body]
49.     pub const fn new_with_pred(
50.         val: T,
51.         Ghost(predicate): Ghost<P>,
52.         Tracked(state): Tracked<P::State>,
53.     ) -> (res: Self)
54.         requires
55.             predicate.inv(val, state),
56.         ensures
57.             res.predicate() == predicate,
58.     {
59.         unimplemented!()
60.     }
61. 
62.     pub closed spec fn predicate(self) -> P {
63.         self.predicate@
64.     }
65. 
66.     #[verus_spec(ret =>
67.         ensures
68.             ret.predicate() == self.predicate(),
69.             ret.predicate_inv(),
70.     )]
71.     #[verifier::external_body]
72.     pub fn lock(&self) -> SpinLockGuard<'_, T, G, P> {
73.         unimplemented!()
74.     }
