77. // Inlined from `sync/spin.rs`.
78. #[verifier::reject_recursive_types(T)]
79. #[verifier::reject_recursive_types(G)]
80. pub struct SpinLockGuard<'a, T, G, P: SpinLockPredicate<T>> {
81.     lock: &'a SpinLock<T, G, P>,
82.     tracked_perm: Tracked<PointsTo<T>>,
83.     tracked_state: Tracked<Option<P::State>>,
84. }
85. 
86. impl<T, G, P: SpinLockPredicate<T>> SpinLockGuard<'_, T, G, P> {
87.     pub closed spec fn value(self) -> T {
88.         *self.tracked_perm@.value()
89.     }
90. 
91.     pub closed spec fn predicate_state(self) -> P::State
92.         recommends
93.             self.has_predicate_state(),
94.     {
95.         self.tracked_state@->0
96.     }
97. 
98.     pub closed spec fn has_predicate_state(self) -> bool {
99.         self.tracked_state@ is Some
100.     }
101. 
102.     pub closed spec fn predicate(self) -> P {
103.         self.lock.predicate()
104.     }
105. 
106.     pub open spec fn predicate_inv(self) -> bool {
107.         &&& self.has_predicate_state()
108.         &&& self.predicate().inv(self.value(), self.predicate_state())
109.     }
110. 
111.     pub open spec fn view(self) -> T {
112.         self.value()
113.     }
114. 
115.     #[verus_spec(ret =>
116.         with
117.             -> state: Tracked<P::State>,
118.         requires
119.             old(self).has_predicate_state(),
120.         ensures
121.             state@ == old(self).predicate_state(),
122.             !final(self).has_predicate_state(),
123.             final(self).value() == old(self).value(),
124.             final(self).predicate() == old(self).predicate(),
125.     )]
126.     #[verifier::external_body]
127.     pub fn take_predicate_state(&mut self) {
128.         unimplemented!()
129.     }
130. 
131.     #[verus_spec(
132.         with
133.             Tracked(state): Tracked<P::State>,
134.         requires
135.             !old(self).has_predicate_state(),
136.         ensures
137.             final(self).has_predicate_state(),
138.             final(self).predicate_state() == state,
139.             final(self).value() == old(self).value(),
140.             final(self).predicate() == old(self).predicate(),
141.     )]
142.     #[verifier::external_body]
143.     pub fn put_predicate_state(&mut self) {
144.         unimplemented!()
145.     }
146. 
147.     #[verus_spec(
148.         requires
149.             self.predicate_inv(),
150.     )]
151.     #[verifier::external_body]
152.     pub fn drop(self) {
153.         unimplemented!()
154.     }
155. }
