167. impl<T, G, P: SpinLockPredicate<T>> DerefMut for SpinLockGuard<'_, T, G, P> {
168.     #[verus_spec(ret =>
169.         ensures
170.             final(self).view() == *final(ret),
171.             old(self).view() == *ret,
172.             final(self).has_predicate_state() == old(self).has_predicate_state(),
173.             old(self).has_predicate_state() ==> final(self).predicate_state()
174.                 == old(self).predicate_state(),
175.             final(self).predicate() == old(self).predicate(),
176.     )]
177.     #[verifier::external_body]
178.     fn deref_mut(&mut self) -> &mut Self::Target {
179.         unimplemented!()
180.     }
