198. impl SpinLockPredicate<VecDeque<Arc<Waker>>> for WakersPredicate {
199.     type State = GhostVar<int>;
200. 
201.     /// While the spin lock is unlocked, its mirror records the exact queue
202.     /// length. Lock acquisition transfers the mirror to the guard, allowing
203.     /// the relation to be updated together with `num_wakers` before unlock.
204.     closed spec fn inv(self, wakers: VecDeque<Arc<Waker>>, mirror: GhostVar<int>) -> bool {
205.         &&& mirror.id() == self.id()
206.         &&& mirror@ == wakers@.len()
207.     }
208. }
