212. /// A wait queue.
213. pub struct WaitQueue {
214.     num_wakers: AtomicU32<_, GhostVarAuth<int>, _>,
215.     wakers: SpinLock<VecDeque<Arc<Waker>>, LocalIrqDisabled, WakersPredicate>,
216. }
217. 
218. closed spec fn wf(self) -> bool {
219.     invariant on num_wakers with (wakers) is (v: u32, g: GhostVarAuth<int>) {
220.         &&& g.id() == wakers.predicate().id()
221.         &&& g@ == v as int
222.     }
223. }
224. }
225. 
226. impl WaitQueue {
227.     #[verifier::type_invariant]
228.     pub closed spec fn type_inv(self) -> bool {
229.         self.wf()
230.     }
231. }
232. 
233. impl WaitQueue {
234.     pub const fn new() -> Self {
235.         proof_decl! {
236.             let tracked (count_auth, count_mirror) = GhostVarAuth::<int>::new(0int);
237.         }
238.         let ghost ghost_id = count_auth.id();
239.         let wakers = SpinLock::new_with_pred(
240.             VecDeque::new(),
241.             Ghost(WakersPredicate { ghost_id: Ghost(ghost_id) }),
242.             Tracked(count_mirror),
243.         );
244.         WaitQueue { num_wakers: AtomicU32::new(Ghost(wakers), 0, Tracked(count_auth)), wakers }
245.     }
246. 
247.     #[track_caller]
248.     #[verus_spec(ret =>
249.         requires
250.             cond.requires(()),
251.         ensures
252.             cond.ensures((), Some(ret)),
253.     )]
254.     #[verifier::exec_allows_no_decreases_clause]
255.     pub fn wait_until<F, R>(&self, mut cond: F) -> R where F: FnMut() -> Option<R> {
256.         if let Some(res) = cond() {
257.             return res;
258.         }
259.         let (waiter, _) = Waiter::new_pair();
260.         #[verus_spec(invariant
261.             cond.requires(()),
262.         )]
263.         loop {
264.             self.enqueue(waiter.waker());
265.             if let Some(res) = cond() {
266.                 assert(cond.ensures((), Some(res)));
267.                 proof! { admit(); }  // FIXME: https://github.com/verus-lang/verus/issues/2295
268.                 return res;
269.             }
270.             waiter.wait();
271.         }
272.     }
273. 
274.     #[verifier::exec_allows_no_decreases_clause]
275.     pub fn wake_one(&self) -> (r: bool) {
276.         proof! { use_type_invariant(self); }
277.         if self.is_empty() {
278.             return false;
279.         }
280.         loop invariant self.wf(), {
281.             let mut wakers = self.wakers.lock();
282.             let Some(waker) = wakers.pop_front() else {
283.                 wakers.drop();
284.                 return false;
285.             };
286.             proof_decl! { let tracked mut count_mirror: GhostVar<int>; }
287.             #[verus_spec(with => Tracked(count_mirror))]
288.             wakers.take_predicate_state();
289.             atomic_with_ghost! {
290.                 self.num_wakers => fetch_sub(1);
291.                 update prev -> next;
292.                 ghost count_auth => {
293.                 }
294.             };
295.             #[verus_spec(with Tracked(count_mirror))]
296.             wakers.put_predicate_state();
297.             wakers.drop();
298.             if waker.wake_up() { return true; }
299.         }
300.     }
301. 
302.     #[verifier::exec_allows_no_decreases_clause]
303.     pub fn wake_all(&self) -> (r: usize) {
304.         proof! { use_type_invariant(self); }
305.         if self.is_empty() { return 0; }
306.         let mut num_woken = 0;
307.         loop invariant self.wf(), {
308.             let mut wakers = self.wakers.lock();
309.             let Some(waker) = wakers.pop_front() else {
310.                 wakers.drop();
311.                 break;
312.             };
313.             proof_decl! { let tracked mut count_mirror: GhostVar<int>; }
314.             #[verus_spec(with => Tracked(count_mirror))]
315.             wakers.take_predicate_state();
316.             atomic_with_ghost! {
317.                 self.num_wakers => fetch_sub(1);
318.                 update prev -> next;
319.                 ghost count_auth => {
320.                 }
321.             };
322.             #[verus_spec(with Tracked(count_mirror))]
323.             wakers.put_predicate_state();
324.             wakers.drop();
325.             if waker.wake_up() {
326.                 assume(num_woken < usize::MAX);
327.                 num_woken += 1;
328.             }
329.         }
330.         num_woken
331.     }
332. 
333.     fn is_empty(&self) -> bool {
334.         proof! { use_type_invariant(self); }
335.         self.num_wakers.load() == 0
336.     }
337. 
338.     #[doc(hidden)]
339.     pub fn enqueue(&self, waker: Arc<Waker>) {
340.         proof! { use_type_invariant(self); }
341.         let mut wakers = self.wakers.lock();
342.         wakers.push_back(waker);
343.         proof_decl! { let tracked mut count_mirror: GhostVar<int>; }
344.         #[verus_spec(with => Tracked(count_mirror))]
345.         wakers.take_predicate_state();
346.         atomic_with_ghost! {
347.             self.num_wakers => fetch_add(1);
348.             update prev -> next;
349.             ghost count_auth => {
350.                 assume(prev < u32::MAX);
351.             }
352.         };
353.         #[verus_spec(with Tracked(count_mirror))]
354.         wakers.put_predicate_state();
355.         wakers.drop();
356.     }
357. }
358. 
359. impl Default for WaitQueue {
360.     fn default() -> Self { Self::new() }
361. }
362. 
363. // Inlined from `sync/wait.rs`.
364. pub struct Waiter { waker: Arc<Waker> }
365. impl !Send for Waiter {}
366. impl !Sync for Waiter {}
367. impl Waiter {
368.     pub closed spec fn rel_waker(self, waker: Arc<Waker>) -> bool { self.waker == waker }
369. }
370. 
371. struct_with_invariants! {
372. pub struct Waker {
373.     has_woken: AtomicBool<_, (), _>,
374.     task: Arc<Task>,
375. }
376. closed spec fn wf(self) -> bool {
377.     invariant on has_woken is (_v: bool, _g: ()) { true }
378. }
379. }
380. 
381. impl Waker {
382.     #[verifier::type_invariant]
383.     pub closed spec fn type_inv(self) -> bool { self.wf() }
384. }
385. 
386. #[verus_verify]
387. impl Waiter {
388.     #[verus_spec(ret => ensures ret.0.rel_waker(ret.1))]
389.     pub fn new_pair() -> (Self, Arc<Waker>) {
390.         let waker = Arc::new(Waker {
391.             has_woken: AtomicBool::new(Ghost(()), false, Tracked(())),
392.             task: Arc::new(Task {}),
393.         });
394.         let waiter = Self { waker: waker.clone() };
395.         (waiter, waker)
396.     }
397. 
398.     #[track_caller]
399.     pub fn wait(&self) { self.waker.do_wait(); }
400. 
401.     #[verus_spec(ret =>
402.         requires cond.requires(()), cancel_cond.requires(()),
403.         ensures match ret {
404.             Ok(res) => cond.ensures((),Some(res)),
405.             Err(e) => cancel_cond.ensures((), Err(e)),
406.         },
407.     )]
408.     #[track_caller]
409.     #[verifier::exec_allows_no_decreases_clause]
410.     pub fn wait_until_or_cancelled<F, R, FCancel, E>(
411.         &self, mut cond: F, cancel_cond: FCancel,
412.     ) -> core::result::Result<R, E> where
413.         F: FnMut() -> Option<R>, FCancel: Fn() -> core::result::Result<(), E>,
414.     {
415.         #[verus_spec(invariant cond.requires(()), cancel_cond.requires(()))]
416.         loop {
417.             if let Some(res) = cond() {
418.                 assert(cond.ensures((), Some(res))) by { admit(); };
419.                 proof! { admit(); }
420.                 return Ok(res);
421.             };
422.             if let Err(e) = cancel_cond() {
423.                 self.waker.close();
424.                 proof! { admit(); }
425.                 return cond().ok_or(e);
426.             }
427.             self.wait();
428.         }
429.     }
430. 
431.     #[verus_spec(ret => ensures self.rel_waker(ret))]
432.     pub fn waker(&self) -> Arc<Waker> { self.waker.clone() }
433.     pub fn task(&self) -> &Arc<Task> { &self.waker.task }
434.     pub fn drop(self) { self.waker.close(); }
435. }
436. 
437. impl Waker {
438.     #[verifier::external_body]
439.     pub fn wake_up(&self) -> bool { unimplemented!() }
440.     #[track_caller]
441.     #[verifier::external_body]
442.     fn do_wait(&self) { unimplemented!() }
443.     fn close(&self) {
444.         proof! { use_type_invariant(self); }
445.         let _ = atomic_with_ghost! {
446.             self.has_woken => swap(true);
447.             update _prev -> _next;
448.             ghost _g => {}
449.         };
450.     }
451. }
452. 
453. } // verus!
454. 
455. // Standalone entry point so `verus wait_inline.rs` uses its default binary
456. // crate mode. The verified wait-queue definitions above do not use it.
457. fn main() {}
458.

